add_action( 'woocommerce_checkout_create_order', 'perfectpixel_phone_country_prefix', 10, 2 );

function perfectpixel_phone_country_prefix( $order, $data ) {
	$phone   = preg_replace( '/[^\d+]/', '', (string) $order->get_billing_phone() );
	$country = $order->get_billing_country();
	if ( '' === $phone || '' === $country || 0 === strpos( $phone, '+' ) || 0 === strpos( $phone, '00' ) ) {
		$order->set_billing_phone( $phone );
		return;
	}
	$code = WC()->countries->get_country_calling_code( $country );
	if ( is_array( $code ) ) {
		$code = reset( $code );
	}
	if ( ! $code ) {
		$order->set_billing_phone( $phone );
		return;
	}
	// The national trunk "0" is dropped after the country code (e.g. UK 07… → +447…), except in Italy/San Marino/Vatican.
	$national = ( '0' === $phone[0] && ! in_array( $country, array( 'IT', 'SM', 'VA' ), true ) ) ? substr( $phone, 1 ) : $phone;
	$order->set_billing_phone( $code . $national );
}
